styles:
/* admin legacy isolation */
.admin-legacy-root, .admin-legacy-root * { box-sizing: border-box; }

/* DC Space Admin ? modern polish layer
   Keeps brand blues + soft cream/gold accents; refines surfaces, type, and motion. */

:root {
  --blue: #448aff;
  --blue-dark: #448aff;
  --blue-link: #448aff;
  --bg: #f3f8fd;
  --text: #3a3544;
  --black: #0f172a;
  --gold: #6b5720;
  --cream-border: #e8eef7;
  --panel: #ffffff;
  --surface: #ffffff;
  --surface-muted: #f7fafc;
  --border-soft: rgba(68, 138, 255, 0.14);
  --border-strong: rgba(68, 138, 255, 0.28);
  --shadow-sm: 0 1px 2px rgba(19, 87, 201, 0.04), 0 4px 14px rgba(68, 138, 255, 0.07);
  --shadow-md: 0 4px 10px rgba(19, 87, 201, 0.05), 0 16px 36px rgba(68, 138, 255, 0.1);
  --radius-sm: 10px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 999px;
  --font-xs: 11px;
  --font-sm: 12px;
  --font-md: 13px;
  --font-base: 14px;
  --font-lg: 15px;
  --font-xl: 18px;
  --font-2xl: 22px;
  --font-3xl: 28px;
}

html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-size: 15px;
}

body {
  background:
    radial-gradient(ellipse 70% 45% at 0% 0%, rgba(68, 138, 255, 0.1), transparent 55%),
    radial-gradient(ellipse 55% 40% at 100% 0%, rgba(203, 238, 243, 0.35), transparent 50%),
    radial-gradient(ellipse 50% 35% at 80% 100%, rgba(245, 210, 157, 0.12), transparent 55%),
    var(--bg);
  color: var(--text);
  font-size: var(--font-base);
  line-height: 1.45;
  letter-spacing: -0.01em;
}

/* ?? Shell ?? */
.app {
  transition: grid-template-columns 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.sidebar {
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-right: 1px solid var(--border-soft);
  padding: 24px 16px 18px;
}

.sidebar::before,
.sidebar::after,
.sidebar-glow {
  opacity: 0.42;
}

.brand-logo {
  border-radius: 12px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.brand-logo:hover {
  transform: translateY(-1px);
}

.nav {
  gap: 4px;
}

.nav a {
  border-radius: 10px;
  font-weight: 600;
  font-size: var(--font-md);
  padding: 10px 12px;
  letter-spacing: -0.015em;
  transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.nav a:hover {
  background: rgba(68, 138, 255, 0.1);
  transform: translateX(2px);
}

.nav a.active {
  background: rgba(68, 138, 255, 0.16);
  box-shadow: inset 0 0 0 1px rgba(68, 138, 255, 0.12);
}

.nav a.att-nav,
.nav a.att-nav.active,
.nav a.att-nav:hover {
  min-height: 0 !important;
  height: auto !important;
  align-items: center !important;
  padding: 10px 12px !important;
  line-height: 1.25 !important;
}

.app.sidebar-collapsed .nav a:hover {
  transform: none;
}

.user-card {
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  padding: 10px;
  box-shadow: var(--shadow-sm);
  background: rgba(255, 255, 255, 0.92);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

a.user-card {
  text-decoration: none;
  color: inherit;
  cursor: pointer;
}

.user-meta strong {
  font-size: var(--font-sm);
}

.user-meta span {
  font-size: 10px;
}

.user-avatar {
  width: 36px;
  height: 36px;
  box-shadow: 0 0 0 3px rgba(68, 138, 255, 0.12);
}

.user-card:hover {
  border-color: var(--border-strong);
  box-shadow: var(--shadow-md);
}

.app.sidebar-collapsed .user-card {
  display: none !important;
}

.app.sidebar-collapsed .brand-text,
.app.sidebar-collapsed .menu-toggle {
  display: none !important;
}

.main {
  padding: 0 28px 48px;
}

.topbar {
  padding: 18px 0 14px;
  margin-bottom: 2px;
}

.topbar::before {
  opacity: 0.85;
  filter: blur(28px);
}

.page-title h1,
.page-heading h1,
.page-heading-row .texts h1 {
  font-family: "Poppins", sans-serif !important;
  font-size: 42px !important;
  font-weight: 600 !important;
  letter-spacing: -0.02em !important;
  line-height: 1.1 !important;
  color: #448AFF !important;
  text-shadow: none !important;
}

.page-title p,
.page-heading p,
.page-heading-row .texts p {
  font-family: "Poppins", sans-serif !important;
  font-size: 22px !important;
  font-weight: 400 !important;
  letter-spacing: -0.02em !important;
  line-height: 1.2 !important;
  color: #448AFF !important;
  opacity: 1 !important;
  margin-top: 2px !important;
}

@media (max-width: 900px) {
  .page-title h1,
  .page-heading h1,
  .page-heading-row .texts h1 {
    font-size: 32px !important;
  }

  .page-title p,
  .page-heading p,
  .page-heading-row .texts p {
    font-size: 18px !important;
  }
}

.welcome p {
  font-family: "Poppins", sans-serif !important;
  font-size: 42px !important;
  font-weight: 600 !important;
  letter-spacing: -0.02em !important;
  line-height: 1.1 !important;
  color: #448AFF !important;
}

.brand-text strong {
  font-size: var(--font-lg);
}

.brand-text span {
  font-size: var(--font-xs);
}

.search-wrap {
  display: inline-flex !important;
  align-items: center !important;
  gap: 10px !important;
}

.search-bar {
  display: inline-flex !important;
  align-items: center !important;
  height: 36px !important;
  width: min(360px, 42vw) !important;
  padding: 0 16px !important;
  gap: 10px !important;
  border: 1px solid rgba(68, 138, 255, 0.22) !important;
  box-shadow: 0 4px 14px rgba(68, 138, 255, 0.12) !important;
  border-radius: 999px !important;
  background: #fff !important;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
  overflow: hidden;
}

.search-bar:focus-within {
  border-color: rgba(68, 138, 255, 0.4) !important;
  box-shadow: 0 0 0 3px rgba(68, 138, 255, 0.1), 0 4px 14px rgba(68, 138, 255, 0.14) !important;
}

.search-bar input {
  flex: 1 1 auto !important;
  font-size: 13px !important;
  color: #64748b !important;
  min-width: 0;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
}

.search-bar input::placeholder {
  color: #94a3b8 !important;
}

.search-bar > svg {
  width: 18px !important;
  height: 18px !important;
  flex-shrink: 0;
}

.search-filter,
.heading-actions > .icon-btn.search-filter,
.search-wrap > .icon-btn {
  width: 28px !important;
  height: 28px !important;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  color: #448aff !important;
  padding: 0 !important;
  display: grid !important;
  place-items: center !important;
  flex-shrink: 0;
  border-radius: 8px;
  transition: background 0.15s ease, transform 0.15s ease;
}

.search-filter:hover,
.search-wrap > .icon-btn:hover {
  background: rgba(68, 138, 255, 0.08) !important;
}

.search-filter svg,
.search-wrap > .icon-btn svg {
  width: 20px !important;
  height: 20px !important;
}

.icon-btn svg {
  width: 22px;
  height: 22px;
}

.search-bar.gold {
  height: 36px !important;
  width: min(360px, 100%) !important;
  border-color: rgba(68, 138, 255, 0.22) !important;
  border-radius: 999px !important;
  box-shadow: 0 4px 14px rgba(68, 138, 255, 0.12) !important;
  background: #fff !important;
}

.section-heading .heading-actions {
  margin-left: auto !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 10px !important;
}

.section-heading .heading-actions .search-bar {
  width: min(340px, 46vw) !important;
}

.icon-btn {
  transition: transform 0.15s ease, opacity 0.15s ease;
  border-radius: 10px;
}

.icon-btn:hover {
  transform: translateY(-1px);
  opacity: 0.88;
}

/* ?? Stats / dashboard cards ?? */
.panel-box,
.events-panel,
.detail-card,
.metric-card,
.report-card,
.feedback-card,
.cert-card {
  border-radius: var(--radius-md);
}

.stat-card {
  min-height: 96px;
  padding: 16px 14px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-sm);
  transition: box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

.stat-card:hover {
  border-color: var(--border-strong);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.stat-value {
  font-size: var(--font-3xl) !important;
  line-height: 1.1;
}

.stat-label {
  font-size: var(--font-sm) !important;
}

.panel-box {
  background: var(--surface);
  border: 1px solid var(--border-soft) !important;
  border-radius: 14px !important;
  box-shadow: var(--shadow-sm) !important;
  padding: 16px 18px 18px !important;
}

.panel-head h3,
.panel-title,
.section-title,
.activity-trigger {
  font-size: 15px !important;
  font-weight: 650 !important;
  color: #448AFF !important;
}

.section-title {
  font-size: 22px !important;
  font-weight: 700 !important;
  letter-spacing: -0.02em !important;
  margin: 8px 0 14px !important;
}

.activity-trigger svg path {
  stroke: #448AFF !important;
}

.activity-menu {
  border: 1px solid var(--border-soft) !important;
  border-radius: 12px !important;
  box-shadow: var(--shadow-md) !important;
}

.activity-menu button:hover,
.activity-menu button.active {
  background: #f3f8ff !important;
  color: #448AFF !important;
}

.filter-btn,
.sort-btn,
.sort-bar {
  background: #fff !important;
  border: 1.5px solid #448AFF !important;
  border-radius: 8px !important;
  color: #448AFF !important;
  font-weight: 600 !important;
  height: 32px !important;
}

.filter-btn:hover,
.sort-btn:hover {
  background: #448AFF !important;
  color: #fff !important;
}

.home12 thead th,
.panel-box thead th,
#recent-activities thead th {
  background: #f3f8ff !important;
  color: #448AFF !important;
  border-bottom: 1px solid rgba(68, 138, 255, 0.16) !important;
}

.panel-box tbody td,
#recent-activities tbody td {
  border-bottom: 1px solid rgba(68, 138, 255, 0.1) !important;
  color: #1e293b !important;
}

.panel-box tbody tr:hover td,
#recent-activities tbody tr:hover td {
  background: rgba(68, 138, 255, 0.03) !important;
}

.view-btn {
  height: 28px !important;
  min-width: 72px !important;
  padding: 0 12px !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  border-radius: 8px !important;
  border: 1.5px solid #448AFF !important;
  background: rgba(68, 138, 255, 0.12) !important;
  color: #448AFF !important;
}

.view-btn:hover {
  background: #448AFF !important;
  color: #fff !important;
  transform: translateY(-1px);
}

.table-footer {
  color: #448AFF !important;
}

.pager button {
  border: 1.5px solid #448AFF !important;
  border-radius: 8px !important;
  color: #448AFF !important;
  background: #fff !important;
}

.pager button:hover {
  background: #448AFF !important;
  color: #fff !important;
}

.type-filter-trigger {
  color: #448AFF !important;
}

.type-filter-menu {
  border: 1px solid var(--border-soft) !important;
  border-radius: 8px !important;
  box-shadow: var(--shadow-md) !important;
}

.type-filter-menu button:hover,
.type-filter-menu button.active {
  background: #f3f8ff !important;
  color: #448AFF !important;
}

.event-card {
  min-height: 108px;
  padding: 12px 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: background-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}

.event-card:hover {
  background: #f3f8ff;
  border-color: var(--border-strong);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.event-card h4 {
  font-size: var(--font-md);
  line-height: 1.3;
}

.event-card .meta-label {
  font-size: 10px;
}

.event-card .meta-value {
  font-size: var(--font-sm);
}

/* ?? Events list ?? */
.event-tabs {
  gap: 4px;
  border-bottom-width: 3px;
  border-bottom-color: rgba(68, 138, 255, 0.85);
}

.event-tabs button {
  border-radius: 10px 14px 0 0;
  font-weight: 600;
  font-size: var(--font-sm);
  padding: 10px 14px 12px;
  letter-spacing: -0.015em;
  transition: background 0.18s ease, color 0.18s ease, filter 0.18s ease;
}

.event-tabs button:hover:not(.active) {
  background: rgba(68, 138, 255, 0.1);
}

.event-tabs button.active { filter: none; }

.section-heading {
  margin: 18px 0 12px;
  font-size: var(--font-xl);
  text-shadow: none;
}

.section-heading .heading-text {
  font-size: var(--font-xl);
  letter-spacing: -0.02em;
  font-weight: 700;
}

.chip {
  height: 28px;
  padding: 0 12px 0 12px;
  font-size: var(--font-xs);
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-soft) !important;
  background: #f3f8ff !important;
  color: var(--blue-link) !important;
  font-weight: 600;
  transition: background 0.15s ease, border-color 0.15s ease, opacity 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.chip:hover {
  background: #e8f1ff !important;
  border-color: var(--border-strong) !important;
  box-shadow: var(--shadow-sm) !important;
  transform: translateY(-1px);
}

.chip.is-inactive {
  opacity: 0.45;
}

.events-panel {
  background: #fff !important;
  border: 1px solid var(--border-soft) !important;
  box-shadow: var(--shadow-sm) !important;
  border-radius: 14px !important;
  padding: 10px !important;
}

.event-item,
a.event-item {
  display: grid !important;
  grid-template-columns: 120px minmax(0, 1fr) !important;
  gap: 12px !important;
  align-items: center !important;
  padding: 10px !important;
  margin-bottom: 8px !important;
  min-height: 0 !important;
  background: #ffffff !important;
  border: 1px solid var(--border-soft) !important;
  border-radius: 12px !important;
  box-shadow: var(--shadow-sm) !important;
  text-decoration: none;
  color: inherit;
  cursor: pointer;
  transition: background-color 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease, transform 0.2s ease !important;
}

.event-item:last-of-type,
a.event-item:last-of-type {
  margin-bottom: 0 !important;
}

.event-item:hover,
a.event-item:hover {
  background: #f8fbff !important;
  border-color: var(--border-strong) !important;
  box-shadow: var(--shadow-md) !important;
  transform: translateY(-2px);
}

/* Blue photo holders (lists + detail posters) */
.event-thumb,
.event-thumb.solid,
.submit-meta .poster,
.poster,
.detail-top-meta .poster {
  width: 100% !important;
  height: 68px !important;
  border-radius: 10px !important;
  background: linear-gradient(145deg, #7eb6ff 0%, #448aff 48%, #3476e3 100%) !important;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.28) !important;
  flex-shrink: 0;
}

.submit-meta .poster,
.poster,
.detail-top-meta .poster {
  width: 140px !important;
  height: 68px !important;
  margin-left: auto;
}

.event-thumb.solid {
  display: grid;
  place-items: center;
}

.event-thumb.solid span {
  width: 70%;
  height: 70%;
  border-radius: 8px;
  background: linear-gradient(135deg, #5a9dff, #b4d6ff) !important;
}

.event-info h3 {
  font-size: 14px !important;
  font-weight: 650 !important;
  color: #1e293b !important;
  margin-bottom: 4px !important;
  letter-spacing: -0.015em;
  line-height: 1.3 !important;
}

.event-info p {
  font-size: 12px !important;
  font-weight: 500 !important;
  color: #64748b !important;
  line-height: 1.35 !important;
}

.events-footer {
  margin-top: 10px !important;
  padding-top: 10px !important;
  font-size: var(--font-xs);
  border-top: 1px solid var(--border-soft) !important;
  color: var(--blue-link) !important;
}

.sort-btn,
.pager button {
  font-size: var(--font-xs);
  border-radius: 8px;
  color: var(--blue-link) !important;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.sort-btn:hover,
.pager button:hover {
  background: rgba(68, 138, 255, 0.08);
}

.section-heading {
  margin: 14px 0 10px !important;
  font-size: var(--font-xl) !important;
  text-shadow: none !important;
}

.section-heading .heading-text {
  font-size: var(--font-xl) !important;
  letter-spacing: -0.02em;
  font-weight: 700;
  color: var(--blue-link) !important;
}

.section-heading .accent {
  color: #448aff !important;
}

.search-bar.gold {
  border-color: rgba(68, 138, 255, 0.22) !important;
  background: #fff !important;
  height: 36px !important;
  width: min(360px, 100%) !important;
  border-radius: 999px !important;
}

.search-bar.gold svg circle,
.search-bar.gold svg path,
.search-bar.gold .icon-btn {
  color: var(--blue-link) !important;
  stroke: #448aff !important;
}

.filter-row {
  gap: 8px !important;
  margin-bottom: 10px !important;
}

.events-filter-menu {
  border: 1px solid var(--border-soft) !important;
  border-radius: 12px !important;
  box-shadow: var(--shadow-md) !important;
  background: #ffffff!important;
}

.events-filter-menu button:hover,
.events-filter-menu button.active {
  background: #f3f8ff !important;
  color: var(--blue-link) !important;
}

/* Dashboard event summary cards */
.card-row {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 12px !important;
  margin-bottom: 20px !important;
}

.event-card {
  min-height: 0 !important;
  padding: 14px 14px 12px !important;
  background: #fff !important;
  border: 1px solid var(--border-soft) !important;
  border-radius: 14px !important;
  box-shadow: var(--shadow-sm) !important;
  gap: 4px !important;
  transition: background-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease, border-color 0.2s ease !important;
}

.event-card:hover {
  background: #f8fbff !important;
  border-color: var(--border-strong) !important;
  box-shadow: var(--shadow-md) !important;
  transform: translateY(-2px);
}

.event-card h4 {
  font-size: 14px !important;
  font-weight: 650 !important;
  color: var(--blue-link) !important;
  line-height: 1.3 !important;
}

.event-card .meta-label {
  font-size: 10px !important;
  color: #64748b !important;
}

.event-card .meta-value {
  font-size: 12px !important;
  color: #475569 !important;
}

@media (max-width: 1100px) {
  .card-row {
    grid-template-columns: 1fr !important;
  }

  .event-item,
  a.event-item {
    grid-template-columns: 100px minmax(0, 1fr) !important;
  }
}

/* ?? Detail / forms ?? */
.detail-card,
.metric-card {
  border: 1px solid var(--border-soft);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.analytics-section,
.detail-actions,
.section-head {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.detail-actions {
  padding: 0;
}

.detail-card {
  border-radius: var(--radius-lg);
  padding: clamp(14px, 1.8vw, 20px);
}

.detail-card h3,
.detail-top h3 {
  font-size: var(--font-xl) !important;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: #1e293b !important;
}

.detail-top .desc {
  font-size: var(--font-sm);
}

.detail-actions h2,
.section-head h2 {
  font-size: var(--font-xl) !important;
  text-shadow: none !important;
}

.metric-value {
  font-size: var(--font-xl);
}

.metric-label {
  font-size: var(--font-xs);
}

.action-btn {
  min-height: 34px;
  padding: 0 14px;
  font-size: var(--font-md);
  border-radius: 10px;
  font-weight: 600;
  letter-spacing: -0.01em;
  transition: filter 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}

.action-btn:hover {
  transform: translateY(-1px);
  filter: brightness(1.03);
}

.action-btn.approve {
  box-shadow: 0 4px 14px rgba(68, 138, 255, 0.28);
}

/* ?? Modals / overlays ?? */
.approve-overlay,
.reject-overlay,
.revision-overlay,
[class*="-overlay"] {
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.approve-dialog,
.reject-dialog,
.revision-dialog,
[class$="-dialog"] {
  border-radius: 20px;
  border: 1px solid var(--border-soft);
  box-shadow: var(--shadow-md);
}

.approve-yes,
