      :root {
        --blue: #448aff;
        --blue-dark: #448aff;
        --blue-link: #448aff;
        --bg: #f6fcff;
        --text: #433d4b;
        --black: #000000;
        --gold: #604d18;
        --cream-border: #ffedd3;
        --panel: #fffdfb;
      }

      * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
      }

      body {
        font-family: "Montserrat", sans-serif;
        background: var(--bg);
        color: var(--text);
        min-height: 100vh;
      }

      .app {
        display: grid;
        grid-template-columns: 260px 1fr;
        min-height: 100vh;
        transition: grid-template-columns 0.25s ease;
      }

      .app.sidebar-collapsed {
        grid-template-columns: 78px 1fr;
      }

      /* —— Sidebar —— */
      .sidebar {
        position: relative;
        background: rgba(255, 255, 255, 0.52);
        padding: 28px 18px 20px;
        display: flex;
        flex-direction: column;
        overflow: hidden;
        min-height: 100vh;
        transition: padding 0.25s ease;
      }

      .app.sidebar-collapsed .sidebar {
        padding: 28px 10px 20px;
        align-items: center;
      }

      .sidebar::before,
      .sidebar::after {
        content: "";
        position: absolute;
        width: 220px;
        height: 200px;
        border-radius: 50%;
        filter: blur(50px);
        opacity: 0.5;
        pointer-events: none;
        left: -60px;
      }

      .sidebar::before {
        top: 80px;
        background: rgba(68, 138, 255, 0.2);
      }

      .sidebar::after {
        top: 320px;
        background: rgba(245, 210, 157, 0.2);
      }

      .sidebar-glow {
        position: absolute;
        width: 220px;
        height: 200px;
        left: -60px;
        bottom: 80px;
        border-radius: 50%;
        background: #cbeef3;
        opacity: 0.5;
        filter: blur(50px);
        pointer-events: none;
      }

      .brand {
        position: relative;
        z-index: 1;
        display: flex;
        align-items: center;
        gap: 12px;
        margin-bottom: 28px;
        width: 100%;
      }

      .app.sidebar-collapsed .brand {
        justify-content: center;
        margin-bottom: 32px;
      }

      .brand-logo {
        position: relative;
        width: 48px;
        height: 48px;
        border-radius: 50%;
        background: #448aff;
        box-shadow: 3px 3px 4px #2ca6de;
        display: grid;
        place-items: center;
        overflow: hidden;
        flex-shrink: 0;
        border: none;
        padding: 0;
        cursor: default;
      }

      .app.sidebar-collapsed .brand-logo {
        width: 48px;
        height: 48px;
        cursor: pointer;
        transition: background 0.15s ease, box-shadow 0.15s ease, border-radius 0.15s ease;
      }

      .brand-logo img {
        width: 40px;
        height: auto;
        mix-blend-mode: screen;
        pointer-events: none;
      }

      .app.sidebar-collapsed .brand-logo img {
        width: 36px;
      }

      .brand-logo .expand-icon {
        display: none;
        width: 28px;
        height: 28px;
        pointer-events: none;
      }

      .app.sidebar-collapsed .brand-logo:hover {
        background: transparent;
        box-shadow: none;
        border-radius: 8px;
      }

      .app.sidebar-collapsed .brand-logo:hover img {
        display: none;
      }

      .app.sidebar-collapsed .brand-logo:hover .expand-icon {
        display: block;
        transform: scaleX(-1);
      }

      .brand-text {
        flex: 1;
        min-width: 0;
        overflow: hidden;
        transition: opacity 0.2s ease, width 0.2s ease;
      }

      .app.sidebar-collapsed .brand-text {
        display: none;
      }

      .brand-text strong {
        display: block;
        font-size: 18px;
        font-weight: 800;
        color: var(--blue);
        letter-spacing: -0.02em;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.15);
      }

      .brand-text span {
        display: block;
        font-size: 12px;
        font-weight: 700;
        color: var(--blue-dark);
        letter-spacing: -0.02em;
      }

      .menu-toggle {
        flex-shrink: 0;
        width: 28px;
        height: 28px;
        border: none;
        background: transparent;
        padding: 0;
        cursor: pointer;
        display: grid;
        place-items: center;
        transition: transform 0.25s ease;
      }

      .menu-toggle svg {
        width: 24px;
        height: 24px;
        display: block;
      }

      .app.sidebar-collapsed .menu-toggle {
        display: none;
      }

      .nav {
        position: relative;
        z-index: 1;
        display: flex;
        flex-direction: column;
        gap: 6px;
        flex: 1;
        width: 100%;
      }

      .app.sidebar-collapsed .nav {
        align-items: center;
        gap: 10px;
      }

      .nav a {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 12px 14px;
        border-radius: 8px;
        text-decoration: none;
        color: var(--blue);
        font-size: 16px;
