        border: 0.5px solid var(--blue);
        min-height: 120px;
        height: 100%;
        padding: 20px 16px 18px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 12px;
        text-align: center;
      }

      .stat-card:nth-child(1) {
        border-radius: 24px 24px 0 24px;
      }
      .stat-card:nth-child(2) {
        border-radius: 24px 24px 0 0;
