        content: "";
        position: absolute;
        width: 180px;
        height: 140px;
        border-radius: 50%;
        filter: blur(50px);
        right: -20px;
        top: -20px;
        opacity: 0.55;
        pointer-events: none;
      }

      .stat-card:nth-child(1)::before {
        background: #f1aaff;
      }
      .stat-card:nth-child(2)::before {
        background: #f5d29d;
        opacity: 0.42;
      }
      .stat-card:nth-child(3)::before {
        background: #ffacd7;
        opacity: 0.58;
        left: -40px;
        right: auto;
      }
      .stat-card:nth-child(4)::before {
        background: #b1ffac;
      }
      .stat-card:nth-child(5)::before {
        background: #06b8ff;
        opacity: 0.54;
      }
      .stat-card:nth-child(6)::before {
        background: #ffb8b8;
        left: -30px;
        right: auto;
      }

      .stat-value {
        position: relative;
        z-index: 1;
        width: 100%;
        font-size: 40px;
        font-weight: 700;
        line-height: 1;
        text-align: center;
      }

      .stat-card:nth-child(1) .stat-value {
        color: #552c8d;
      }
      .stat-card:nth-child(2) .stat-value {
        color: #c49b08;
      }
      .stat-card:nth-child(3) .stat-value {
        color: #d72f72;
      }
      .stat-card:nth-child(4) .stat-value {
        color: #34a939;
      }
      .stat-card:nth-child(5) .stat-value {
        color: #448aff;
      }
      .stat-card:nth-child(6) .stat-value {
        color: #e53535;
      }

      .stat-label {
        position: relative;
        z-index: 1;
        width: 100%;
        font-size: 15px;
        font-weight: 700;
        line-height: 1.2;
        color: var(--text);
        text-align: center;
      }

      .section-title {
        font-size: 22px;
        font-weight: 700;
        color: var(--black);
        margin: 8px 0 14px;
      }

      /* Event cards */
      .card-row {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 14px;
        margin-bottom: 24px;
      }

      .event-card {
        background: #ffffff;
        border: 1px solid var(--blue);
        border-radius: 12px;
        padding: 14px 16px;
        min-height: 130px;
        display: flex;
        flex-direction: column;
        gap: 6px;
        transition: background-color 0.2s ease, box-shadow 0.2s ease;
        cursor: pointer;
      }

      .event-card:hover {
        background: #ebf3ff;
        box-shadow: 2px 2px 12px rgba(68, 138, 255, 0.35);
      }

      .event-card h4 {
        font-size: 14px;
        font-weight: 600;
        color: var(--blue);
        line-height: 1.25;
      }

      .event-card .meta-label {
        margin-top: auto;
        font-size: 10px;
        font-weight: 500;
        color: var(--text);
        text-transform: uppercase;
      }

      .event-card .meta-value {
        font-family: "Poppins", sans-serif;
        font-size: 12px;
        font-weight: 400;
        color: var(--blue-link);
      }

      /* Table */
      .panel-box {
        background: var(--panel);
        border: 2px solid var(--cream-border);
        border-radius: 7px;
        padding: 14px 16px 18px;
        margin-bottom: 28px;
      }

      .panel-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 12px;
      }

      .panel-head h3 {
        font-size: 16px;
        font-weight: 600;
        color: var(--black);
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .activity-select {
        position: relative;
      }

      .activity-trigger {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        border: none;
        background: transparent;
        font-family: inherit;
        font-size: 16px;
        font-weight: 600;
        color: var(--black);
        cursor: pointer;
        padding: 0;
      }

      .activity-trigger svg {
        transition: transform 0.15s ease;
      }

      .activity-select.open .activity-trigger svg {
        transform: rotate(180deg);
      }

      .activity-menu {
        position: absolute;
        top: calc(100% + 8px);
        left: 0;
        min-width: 260px;
        background: #fff;
        border: 1px solid #ffedd3;
        border-radius: 8px;
        box-shadow: 0 8px 24px rgba(96, 77, 24, 0.12);
        padding: 6px;
        z-index: 20;
        display: none;
      }

      .activity-select.open .activity-menu {
        display: block;
      }

      .activity-menu button {
        display: block;
        width: 100%;
        text-align: left;
        border: none;
        background: transparent;
        padding: 10px 12px;
        border-radius: 6px;
        font-family: inherit;
        font-size: 13px;
        font-weight: 500;
        color: var(--black);
        cursor: pointer;
      }

      .activity-menu button:hover,
      .activity-menu button.active {
        background: #fff6e7;
        color: var(--gold);
      }

      .activity-panel {
        display: none;
      }

      .activity-panel.active {
        display: block;
      }

      .type-filter {
        position: relative;
        display: inline-block;
      }

      .type-filter-trigger {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        border: none;
        background: transparent;
        padding: 0;
        font-family: inherit;
        font-size: 11px;
        font-weight: 600;
        letter-spacing: 0.02em;
        color: var(--gold);
        cursor: pointer;
        text-transform: uppercase;
      }

      .type-filter-menu {
        position: absolute;
        top: calc(100% + 6px);
        left: 0;
        min-width: 120px;
        background: #fff;
        border: 1px solid #ffedd3;
        border-radius: 6px;
        box-shadow: 0 8px 20px rgba(96, 77, 24, 0.12);
        padding: 4px;
        z-index: 25;
        display: none;
      }

      .type-filter.open .type-filter-menu {
        display: block;
      }

      .type-filter-menu button {
        display: block;
        width: 100%;
        text-align: left;
        border: none;
        background: transparent;
        padding: 8px 10px;
        border-radius: 4px;
        font-family: inherit;
        font-size: 12px;
        font-weight: 500;
        color: var(--black);
        cursor: pointer;
        text-transform: none;
        letter-spacing: normal;
      }

      .type-filter-menu button:hover,
      .type-filter-menu button.active {
        background: #fff6e7;
        color: var(--gold);
      }

      .filter-btn {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        height: 28px;
        padding: 0 10px;
        background: rgba(245, 210, 157, 0.2);
        border: 0.3px solid #f5d29d;
        border-radius: 4px;
        font-family: "Poppins", sans-serif;
        font-size: 12px;
        font-weight: 500;
        color: var(--gold);
        cursor: pointer;
      }

      .badge {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 4px 10px;
        border-radius: 999px;
        font-size: 11px;
        font-weight: 600;
        white-space: nowrap;
        border: 1px solid transparent;
      }

      .badge.eroom {
        background: #ffe5e8;
        border-color: #f5a3ad;
        color: #c43b4a;
      }

      .badge.dcspace {
        background: #e8f0ff;
        border-color: #8ab6ff;
        color: #448AFF;
      }

      .badge.late {
        background: #fff6d6;
        border-color: #f0d36a;
        color: #9a7b00;
      }

      .badge.present {
        background: #e8f0ff;
        border-color: #8ab6ff;
        color: #448AFF;
      }

      .badge.requirement {
        background: #e7f8ea;
        border-color: #7ed089;
        color: #1f8a3a;
      }

      .badge.undertime {
        background: #ffe5e8;
        border-color: #f5a3ad;
        color: #c43b4a;
      }

      .badge.qualified {
        background: #e4f7f6;
        border-color: #6ecfc8;
        color: #0f7f78;
      }

      .badge.not-qualified {
        background: #fff0e0;
        border-color: #f0b36a;
        color: #b86a00;
      }

      .stars {
        display: inline-flex;
        gap: 2px;
        color: #e6b422;
        letter-spacing: 1px;
        font-size: 13px;
      }

      .stars .empty {
        color: #d0d0d0;
      }

      .sort-group {
        display: inline-flex;
        gap: 8px;
      }

      .sort-btn {
        display: inline-flex;
        align-items: center;
        gap: 4px;
        height: 28px;
        padding: 0 10px;
        background: rgba(245, 210, 157, 0.2);
        border: 0.3px solid #f5d29d;
        border-radius: 4px;
        font-family: "Poppins", sans-serif;
        font-size: 11px;
        font-weight: 500;
        color: var(--gold);
        cursor: pointer;
      }

      .table-wrap {
        overflow-x: auto;
      }

      table {
        width: 100%;
        border-collapse: collapse;
        font-size: 12px;
      }

      thead th {
        background: #fff6e7;
        color: var(--gold);
        font-weight: 600;
        text-align: left;
        padding: 10px 8px;
        letter-spacing: 0.02em;
        font-size: 11px;
      }

      tbody td {
        padding: 12px 8px;
        border-bottom: 1px solid rgba(217, 217, 217, 0.7);
        color: var(--black);
        font-weight: 400;
        vertical-align: middle;
      }

      tbody tr:last-child td {
        border-bottom: none;
      }

      .view-btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 72px;
        height: 26px;
        background: rgba(68, 138, 255, 0.2);
        border: 0.3px solid var(--blue);
        border-radius: 4px;
        color: var(--blue);
        font-size: 12px;
        font-weight: 500;
        text-decoration: none;
        cursor: pointer;
      }

      .table-footer {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        margin-top: 14px;
        flex-wrap: wrap;
        font-size: 12px;
        color: var(--gold);
      }

      .sort-bar {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        height: 28px;
        padding: 0 8px;
        background: rgba(245, 210, 157, 0.2);
        border: 0.3px solid #f5d29d;
        border-radius: 4px;
        font-family: "Poppins", sans-serif;
        font-size: 11px;
        font-weight: 500;
        color: var(--gold);
      }

      .pager {
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .pager button {
        width: 32px;
        height: 28px;
        background: #fff;
        border: 0.3px solid var(--gold);
        border-radius: 2px;
        color: var(--gold);
        cursor: pointer;
      }

      /* Bottom charts / notifs */
      .bottom-grid {
        display: grid;
        grid-template-columns: 1.7fr 1fr;
        gap: 18px;
        align-items: start;
      }

      .chart-box,
      .side-box {
        background: var(--panel);
        border: 2px solid var(--cream-border);
        box-shadow: 3px 3px 28px rgba(245, 210, 157, 0.2);
        border-radius: 6px;
        padding: 16px 18px;
        margin-bottom: 16px;
      }

      .chart-box h4,
      .side-box h4 {
        font-size: 15px;
        font-weight: 600;
        margin-bottom: 12px;
        color: var(--black);
        display: flex;
        align-items: center;
        justify-content: space-between;
      }

      .chart-box h4 span,
      .side-box h4 span {
        font-weight: 400;
        font-size: 13px;
      }

      .bars {
        display: flex;
        align-items: flex-end;
        justify-content: space-between;
        gap: 6px;
        height: 140px;
        margin-bottom: 8px;
      }

      .bars span {
        flex: 1;
        background: #f5d29d;
        border-radius: 6px 6px 0 0;
        min-height: 20px;
      }

      .bars span.active {
        background: var(--blue);
      }

      .months {
        display: flex;
        justify-content: space-between;
        font-size: 10px;
        font-weight: 500;
        color: var(--gold);
      }

      .chart-caption {
        text-align: center;
        font-size: 12px;
        color: #4e3b06;
        margin-top: 10px;
      }

      .notif-item,
      .task-item {
        display: grid;
        grid-template-columns: 16px 1fr;
        gap: 10px;
        padding: 10px 0;
        border-bottom: 1px solid rgba(217, 217, 217, 0.4);
      }

      .notif-item:last-child,
      .task-item:last-child {
        border-bottom: none;
      }

      .dot {
        width: 14px;
        height: 14px;
        border-radius: 50%;
        margin-top: 2px;
        box-shadow: inset 0 0 0 3px #fff;
      }

      .dot.blue {
        background: #a5c7ff;
      }
      .dot.yellow {
        background: #ffe596;
      }
      .dot.red {
        background: #fca8af;
      }

      .notif-item strong,
      .task-item strong {
        display: block;
        font-size: 12px;
        font-weight: 600;
        color: var(--black);
        margin-bottom: 2px;
      }

      .notif-item p,
      .task-item p {
        font-size: 9px;
        font-weight: 400;
        color: var(--black);
        line-height: 1.3;
      }

      .task-item input {
        margin-top: 2px;
        accent-color: var(--blue);
      }

      .rank-list {
        display: flex;
        flex-direction: column;
        gap: 12px;
      }

      .rank-row {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 8px;
        align-items: end;
      }

      .rank-row span {
        font-size: 13px;
      }

      .rank-row small {
        font-size: 11px;
        font-style: italic;
        color: #023fa6;
        text-align: right;
      }

      .bar-track {
        grid-column: 1 / -1;
        height: 8px;
        background: #8ab6ff;
        border-radius: 4px;
        overflow: hidden;
      }

      .bar-fill {
        height: 100%;
        background: var(--blue);
      }

      .legend {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 10px 24px;
        margin-top: 16px;
      }

      .legend span {
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 13px;
      }

      .legend i {
        width: 16px;
        height: 16px;
        border-radius: 50%;
      }

      @media (max-width: 1100px) {
        .app {
          grid-template-columns: 1fr;
        }

        .sidebar {
          min-height: auto;
        }

        .stats,
        .card-row {
          grid-template-columns: 1fr;
        }

        .bottom-grid {
          grid-template-columns: 1fr;
        }

        .search-bar {
          width: 180px;
        }
      }
    
      .info-page {
        padding-bottom: 48px;
      }

      .info-topbar {
        display: flex;
        flex-wrap: wrap;
        align-items: flex-start;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 22px;
      }

      .info-top-left {
        display: flex;
        align-items: flex-start;
        gap: 18px;
      }

      .info-back {
        display: grid;
        place-items: center;
        width: 40px;
        height: 40px;
        margin-top: 10px;
        color: #448aff;
        text-decoration: none;
      }

      .info-back svg {
        width: 28px;
        height: 28px;
      }

      .info-heading h1 {
        font-family: "Poppins", sans-serif;
        font-size: 42px;
        font-weight: 600;
        letter-spacing: -0.02em;
        color: #448aff;
        line-height: 1.1;
      }

      .info-heading p {
        font-family: "Poppins", sans-serif;
        font-size: 22px;
        font-weight: 400;
        letter-spacing: -0.02em;
        color: #448aff;
        margin-top: 2px;
      }

      .info-layout {
        display: grid;
        grid-template-columns: minmax(0, 1.9fr) minmax(280px, 1fr);
        gap: 24px;
        align-items: start;
      }

      .info-col {
        display: flex;
        flex-direction: column;
        gap: 24px;
        min-width: 0;
      }

      .profile-banner {
        display: flex;
        align-items: center;
        gap: 28px;
        min-height: 180px;
        padding: 28px 32px;
        background: linear-gradient(90deg, #cfe1ff 0%, #f5d29d 100%);
        box-shadow: 4px 4px 29px rgba(68, 138, 255, 0.25);
        border-radius: 24px;
      }

      .profile-avatar {
        position: relative;
        width: 142px;
        height: 142px;
        border-radius: 50%;
        background: #fff;
        box-shadow: 0 0 0 5px #fff;
        flex-shrink: 0;
        display: grid;
        place-items: center;
        overflow: hidden;
        border: none;
        padding: 0;
        cursor: pointer;
      }

      .profile-avatar span:not(.avatar-edit-overlay) {
        width: 100%;
        height: 100%;
        display: grid;
        place-items: center;
        background: radial-gradient(circle at 35% 30%, #e8f1ff, #448aff 70%);
        color: #fff;
        font-family: "Poppins", sans-serif;
        font-size: 42px;
        font-weight: 700;
      }

      .avatar-edit-overlay {
        position: absolute;
        inset: 0;
        border-radius: 50%;
        background: rgba(255, 255, 255, 0.35);
        display: grid;
        place-items: center;
        opacity: 0;
        transition: opacity 0.15s ease;
        pointer-events: none;
      }

      .profile-avatar:hover .avatar-edit-overlay,
      .profile-avatar:focus-visible .avatar-edit-overlay {
        opacity: 1;
      }

      .avatar-edit-overlay svg {
        width: 60px;
        height: 60px;
        color: #448aff;
      }

      .profile-meta h2 {
        font-family: "Poppins", sans-serif;
        font-size: 32px;
        font-weight: 700;
        color: #fff;
        line-height: 1.2;
      }

      .profile-meta p {
        font-family: "Poppins", sans-serif;
        font-size: 20px;
        font-weight: 500;
        color: #fff;
        margin-top: 6px;
        word-break: break-word;
      }

      .info-card {
        background: #fff;
        border: 1px solid #c4c4c4;
        box-shadow: 4px 4px 22px rgba(68, 138, 255, 0.25);
        border-radius: 10px;
        padding: 22px 24px 28px;
      }

      .info-card h3 {
        font-size: 19px;
        font-weight: 700;
        color: #448aff;
        margin-bottom: 18px;
      }

      .info-card-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        margin-bottom: 18px;
      }

      .info-card-head h3 {
        margin-bottom: 0;
      }

      .edit-info-btn {
        display: grid;
        place-items: center;
        width: 32px;
        height: 32px;
        border: none;
        border-radius: 8px;
        background: transparent;
        color: #448aff;
        cursor: pointer;
        flex-shrink: 0;
        transition: background 0.15s ease;
      }

      .edit-info-btn:hover {
        background: rgba(68, 138, 255, 0.12);
      }

      .edit-info-btn svg {
        width: 18px;
        height: 18px;
      }

      .edit-info-btn.is-editing {
        background: rgba(68, 138, 255, 0.16);
      }

      .info-field .value-input {
        width: 100%;
        font-family: "Montserrat", sans-serif;
        font-size: 17px;
        font-weight: 400;
        color: #433d4b;
        line-height: 1.35;
        border: 1px solid transparent;
        background: transparent;
        border-radius: 6px;
        padding: 4px 0;
        outline: none;
      }

      .info-card.editing .value-input {
        border-color: #c3d9ff;
        background: #f6fcff;
        padding: 6px 8px;
      }

      .info-card.editing .value-input:focus {
        border-color: #448aff;
        box-shadow: 0 0 0 2px rgba(68, 138, 255, 0.15);
      }

      .info-card h3.with-icon {
        display: flex;
        align-items: center;
        gap: 10px;
      }

      .info-fields {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 18px 28px;
      }

      .info-field {
        display: flex;
        flex-direction: column;
        gap: 4px;
        min-width: 0;
      }

      .info-field.span-2 {
        grid-column: 1 / -1;
      }

      .info-field .label {
        font-size: 17px;
        font-weight: 600;
        color: #433d4b;
      }

      .info-field .value {
        font-size: 17px;
        font-weight: 400;
        color: #433d4b;
        line-height: 1.35;
      }

      .stat-grid {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 16px;
      }

      .stat-tile {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 10px;
        min-height: 140px;
        padding: 16px 10px;
        border: 1.5px solid #c3d9ff;
        border-radius: 8px;
        text-align: center;
        text-decoration: none;
        color: inherit;
        cursor: pointer;
        transition: transform 0.12s ease, box-shadow 0.12s ease;
      }

      a.stat-tile:hover {
        transform: translateY(-2px);
        box-shadow: 0 4px 14px rgba(68, 138, 255, 0.2);
      }

      .stat-tile.active {
        background: #c3d9ff;
      }

      .stat-tile .stat-label {
        font-size: 16px;
        font-weight: 600;
        color: #433d4b;
        line-height: 1.25;
      }

      .stat-tile.active .stat-label,
      .stat-tile.active .stat-value {
        color: #448AFF;
      }

      .stat-tile .stat-value {
        font-size: 30px;
        font-weight: 600;
        color: #433d4b;
      }

      .attendance-wrap {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
        align-items: center;
      }

      .attendance-stats {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 14px;
      }

      .rate-block {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
      }

      .rate-block .rate-label {
        font-size: 22px;
        font-weight: 600;
        color: #448AFF;
        text-align: center;
      }

      .donut {
        position: relative;
        width: 180px;
        height: 180px;
        border-radius: 50%;
        background: conic-gradient(#448aff 0 95%, #b2cfff 95% 100%);
        display: grid;
        place-items: center;
      }

      .donut::before {
        content: "";
        position: absolute;
        width: 116px;
        height: 116px;
        border-radius: 50%;
        background: #fff;
      }

      .donut span {
        position: relative;
        z-index: 1;
        font-size: 36px;
        font-weight: 700;
        color: #448aff;
      }

      .insight-gauges {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 18px;
        margin-bottom: 20px;
      }

      .gauge {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 12px;
        text-align: center;
      }

      .gauge .g-label {
        font-size: 16px;
        font-weight: 600;
        color: #433d4b;
        text-shadow: 2px 2px 2px rgba(68, 138, 255, 0.25);
      }

      .ring {
        position: relative;
        width: 140px;
        height: 140px;
        border-radius: 50%;
        display: grid;
        place-items: center;
      }

      .ring.blue {
        background: conic-gradient(#448aff 0 95%, #b2cfff 95% 100%);
      }

      .ring.score {
        background: conic-gradient(#448aff 0 90%, #b2cfff 90% 100%);
      }

      .ring.ok {
        border: 20px solid #ceffca;
        background: #fff;
        box-sizing: border-box;
      }

      .ring.blue::before,
      .ring.score::before {
        content: "";
        position: absolute;
        width: 100px;
        height: 100px;
        border-radius: 50%;
        background: #fff;
      }

      .ring span {
        position: relative;
        z-index: 1;
        font-size: 26px;
        font-weight: 700;
        color: #448aff;
      }

      .ring.ok span {
        color: #433d4b;
        font-size: 24px;
      }

      .insight-box {
        background: #c3d9ff;
        border: 1.5px solid #c3d9ff;
        border-radius: 8px;
        padding: 18px 22px;
      }

      .insight-box strong {
        display: block;
        font-size: 17px;
        font-weight: 600;
        color: #448AFF;
        margin-bottom: 8px;
        text-shadow: 2px 2px 2px rgba(68, 138, 255, 0.25);
      }

      .insight-box p {
        font-size: 17px;
        font-weight: 400;
        color: #433d4b;
        text-shadow: 2px 2px 2px rgba(68, 138, 255, 0.25);
      }

      .action-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        min-height: 36px;
        margin-bottom: 10px;
      }

      .action-row > span,
      .action-row > a {
        font-size: 17px;
        font-weight: 500;
        color: #433d4b;
        text-decoration: none;
      }

      .action-row.sub > span {
        font-weight: 400;
        padding-left: 22px;
      }

      .action-group-title {
        font-size: 17px;
        font-weight: 500;
        color: #433d4b;
        margin: 8px 0 6px;
      }

      .action-divider {
        height: 1px;
        background: rgba(68, 138, 255, 0.15);
        margin: 14px 0;
      }

      .toggle {
        position: relative;
        width: 42px;
        height: 24px;
        flex-shrink: 0;
        border: none;
        border-radius: 999px;
        background: #c4c4c4;
        cursor: pointer;
        padding: 0;
      }

      .toggle.on {
        background: #448aff;
      }

      .toggle::after {
        content: "";
        position: absolute;
        top: 3px;
        left: 3px;
        width: 18px;
        height: 18px;
        border-radius: 50%;
        background: #fff;
        transition: transform 0.15s ease;
      }

      .toggle.on::after {
        transform: translateX(18px);
      }

      .link-arrow {
        color: #448aff;
        display: grid;
        place-items: center;
      }

      .status-list .info-field {
        margin-bottom: 14px;
      }

      .activity-list {
        display: flex;
        flex-direction: column;
        gap: 0;
      }

      .activity-item {
        display: grid;
        grid-template-columns: 18px 1fr;
        gap: 14px;
        padding: 14px 0;
        border-bottom: 1px solid rgba(68, 138, 255, 0.33);
      }

      .activity-item:last-child {
        border-bottom: none;
      }

      .activity-dot {
        width: 17px;
        height: 17px;
        border-radius: 50%;
        background: #d2c7ec;
        margin-top: 4px;
      }

      .activity-body {
        min-width: 0;
      }

      .activity-head {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 10px;
      }

      .activity-head strong {
        font-size: 16px;
        font-weight: 600;
        color: #433d4b;
      }

      .activity-head time {
        font-size: 9px;
        font-weight: 600;
        color: #433d4b;
        white-space: nowrap;
      }

      .activity-body p {
        font-size: 15px;
        font-weight: 400;
        color: #433d4b;
        margin-top: 4px;
        line-height: 1.35;
      }

      @media (max-width: 1200px) {
        .info-layout { grid-template-columns: 1fr; }
        .stat-grid { grid-template-columns: repeat(2, 1fr); }
        .attendance-wrap { grid-template-columns: 1fr; }
