/* Event tabs — single solid bar (no light hairline above) */
.event-tabs {
  gap: 4px !important;
  border: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  outline: none !important;
  position: relative !important;
  overflow-x: auto !important;
  overflow-y: hidden !important;
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
  padding-bottom: 4px !important;
  background-color: transparent !important;
}
.event-tabs::-webkit-scrollbar {
  display: none !important;
  height: 0 !important;
  width: 0 !important;
}
.event-tabs::before {
  content: none !important;
  display: none !important;
}
.event-tabs::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  height: 4px !important;
  background: #448aff !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  pointer-events: none !important;
  z-index: 0 !important;
}
.event-tabs button {
  position: relative !important;
  z-index: 1 !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
  filter: none !important;
}
.event-tabs button.active {
  filter: none !important;
  margin-bottom: -4px !important;
  padding-bottom: 16px !important;
}

/* Dialog action rows — do not inherit dialog chrome */
.approve-dialog-actions,
.reject-dialog-actions,
.revision-dialog-actions {
  display: flex !important;
  flex-wrap: wrap !important;
  justify-content: center !important;
  align-items: center !important;
  gap: 12px !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
}
.approve-yes,
.approve-back,
.reject-send,
.reject-cancel,
.revision-send,
.revision-cancel {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 46px !important;
  height: 46px !important;
  min-width: 132px !important;
  padding: 0 22px !important;
  border-radius: 12px !important;
  font-family: "Montserrat", sans-serif !important;
  font-size: 15px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
  box-sizing: border-box !important;
}
.approve-back,
.reject-cancel,
.revision-cancel {
  border: 1.5px solid #448aff !important;
  background: #fff !important;
  color: #448aff !important;
  box-shadow: none !important;
}
.approve-yes,
.reject-send,
.revision-send {
  border: 1.5px solid #448aff !important;
  background: #448aff !important;
  color: #fff !important;
  box-shadow: 0 4px 14px rgba(68, 138, 255, 0.28) !important;
}

/* User card profile menu */
.user-menu {
  position: relative;
  margin-top: auto;
  z-index: 20;
}
.user-menu-popover {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(100% + 10px);
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  background: #fff;
  border: 1px solid rgba(68, 138, 255, 0.45);
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(68, 138, 255, 0.18);
}
.user-menu-popover[hidden] {
  display: none !important;
}
.user-menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 10px;
  background: transparent;
  color: #448aff;
  font-family: "Montserrat", sans-serif;
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}
.user-menu-item:hover,
.user-menu-item:focus-visible {
  background: rgba(68, 138, 255, 0.12);
  outline: none;
}
.user-menu-item.logout {
  color: #e11d48;
}
.user-menu-item.logout:hover,
.user-menu-item.logout:focus-visible {
  background: rgba(225, 29, 72, 0.08);
}
.user-menu-icon {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}
button.user-card {
  width: 100%;
  font: inherit;
  text-align: left;
  cursor: pointer;
  color: inherit;
}
.app.sidebar-collapsed .user-menu {
  display: none !important;
}

/* Super Admin — Administration nav */
.nav-super-only {
  display: none !important;
}
body.is-super-admin .nav-super-only {
  display: flex !important;
}


/* main-search-filter-menu */
.filter-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}
.events-filter-menu {
  display: none;
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 40;
  min-width: 180px;
  padding: 8px;
  background: #ffffff !important;
  border: 1px solid rgba(68, 138, 255, 0.22);
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(19, 87, 201, 0.16);
}
.filter-wrap.open .events-filter-menu {
  display: block !important;
}
.events-filter-menu button {
  display: block;
  width: 100%;
  text-align: left;
  border: none;
  background: #ffffff;
  padding: 10px 12px;
  border-radius: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 13px;
  font-weight: 600;
  color: #1357C9;
  cursor: pointer;
}
.events-filter-menu button:hover,
.events-filter-menu button.active {
  background: #f3f8ff;
  color: #1357C9;
}



/* filter-menu-solid-v2 */
.filter-wrap {
  z-index: 9999 !important;
  isolation: isolate !important;
}
.events-filter-menu,
.filter-wrap .events-filter-menu,
.filter-wrap.open .events-filter-menu {
  background: #ffffff !important;
  background-color: #ffffff !important;
  background-image: none !important;
  opacity: 1 !important;
  mix-blend-mode: normal !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  filter: none !important;
  z-index: 10000 !important;
  border: 1px solid #c5d8f5 !important;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.18) !important;
