(function () {
        const app = document.getElementById("app");
        const menuToggle = document.getElementById("menu-toggle");
        const brandLogo = document.getElementById("brand-logo");
        const params = new URLSearchParams(window.location.search);
        const name = params.get("name") || "Khrystelle Jan G. Esplana";
        const email =
          params.get("email") ||
          name
            .toLowerCase()
            .replace(/[^a-z\s.]/g, "")
            .trim()
            .replace(/\s+/g, ".")
            .replace(/\.+/g, ".") + "@sdca.edu.ph";
        const eventName = params.get("event") || "Leadership Excellence Seminar 2026";
        const org = params.get("org") || "DOMINIXODE";
        const date = params.get("date") || "July 1, 2026";
        const estatus = params.get("estatus") || "COMPLETE";
        const rstatus = params.get("rstatus") || "REGISTERED";

        const setText = (id, text) => {
          const el = document.getElementById(id);
          if (el) el.textContent = text;
        };

        setText("user-name", name);
        setText("user-email", email);
        setText("event-name", eventName);
        setText("event-desc", "Event Description");
        setText("ev-date", date);
        setText("ev-org", org);
        setText("ev-status", estatus);
        setText("reg-status", rstatus);

        const initials = name
          .split(/\s+/)
          .filter(Boolean)
          .slice(0, 2)
          .map((p) => p[0])
          .join("")
          .toUpperCase();
        setText("user-initials", initials || "U");

        const back = document.getElementById("info-back");
        if (back) {
          const q = new URLSearchParams(params);
          q.delete("event");
          q.delete("date");
          q.delete("estatus");
          q.delete("rstatus");
          back.href = "/admin/ereg32?" + q.toString();
        }

        document.querySelectorAll(".rv-collapse").forEach((btn) => {
          btn.addEventListener("click", () => {
            const id = btn.getAttribute("data-target");
            const panel = document.getElementById(id);
            if (!panel) return;
            const open = panel.hasAttribute("hidden");
            if (open) panel.removeAttribute("hidden");
            else panel.setAttribute("hidden", "");
            btn.setAttribute("aria-expanded", open ? "true" : "false");
          });
        });

        function setSidebarCollapsed(collapsed) {
          app.classList.toggle("sidebar-collapsed", collapsed);
          menuToggle.setAttribute("aria-expanded", collapsed ? "false" : "true");
          menuToggle.setAttribute(
            "aria-label",
            collapsed ? "Expand sidebar" : "Collapse sidebar"
          );
          brandLogo.setAttribute(
            "aria-label",
            collapsed ? "Expand sidebar" : "DC Space"
          );
        }

        menuToggle.addEventListener("click", () => {
          setSidebarCollapsed(!app.classList.contains("sidebar-collapsed"));
        });

        brandLogo.addEventListener("click", () => {
          if (app.classList.contains("sidebar-collapsed")) {
            setSidebarCollapsed(false);
          }
        });
      })();

(function () {
  const toggle = document.getElementById("user-menu-toggle");
  const popover = document.getElementById("user-menu-popover");
  const logoutBtn = document.getElementById("user-menu-logout");
  if (!toggle || !popover) return;

  function closeMenu() {
    popover.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
  }

  function openMenu() {
    popover.hidden = false;
    toggle.setAttribute("aria-expanded", "true");
  }

  toggle.addEventListener("click", function (event) {
    event.preventDefault();
    event.stopPropagation();
    if (popover.hidden) openMenu();
    else closeMenu();
  });

  document.addEventListener("click", function (event) {
    if (!event.target.closest(".user-menu")) closeMenu();
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") closeMenu();
  });

  if (logoutBtn) {
    logoutBtn.addEventListener("click", async function () {
      try {
        await fetch("/api/auth/logout", { method: "POST", credentials: "same-origin" });
      try { localStorage.removeItem("dc_admin_role"); } catch (err) {}
      } catch (err) {}
      window.location.href = "/admin/login02";
    });
  }
})();

(function () {
  try {
    var role = localStorage.getItem("dc_admin_role") || "";
    if (role === "super-admin") {
      document.body.classList.add("is-super-admin");
      document.querySelectorAll(".nav-super-only").forEach(function (el) {
        el.hidden = false;
        el.removeAttribute("hidden");
      });
    }
  } catch (err) {}
})();

(function () {
  /* main-search-filter-toggle */
  document.querySelectorAll(".filter-wrap").forEach((wrap) => {
    const btn = wrap.querySelector('[aria-label="Filter"], [aria-label="Search filter"], .search-filter, .icon-btn');
    if (!btn) return;
    if (btn.dataset.filterBound) return;
    btn.dataset.filterBound = "1";
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      document.querySelectorAll(".filter-wrap.open").forEach((w) => {
        if (w !== wrap) w.classList.remove("open");
      });
      wrap.classList.toggle("open");
    });
  });
  if (!window.__dcFilterMenuDocClick) {
    window.__dcFilterMenuDocClick = true;
    document.addEventListener("click", () => {
      document.querySelectorAll(".filter-wrap.open").forEach((w) => w.classList.remove("open"));
    });
  }
})();
